CREATE TABLE renders (id TEXT PRIMARY KEY NOT NULL,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,job_id TEXT NOT NULL UNIQUE,manifest_id TEXT NOT NULL,manifest_hash TEXT NOT NULL,manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),preset TEXT NOT NULL CHECK(preset='FHD_MP4'),version_no INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('QUEUED','SUCCEEDED')),output_asset_id TEXT,checksum TEXT,duration_ms INTEGER,technical_json TEXT,created_at TEXT NOT NULL,UNIQUE(project_id,version_no),UNIQUE(id,project_id),FOREIGN KEY(job_id,project_id) REFERENCES jobs(id,project_id) ON DELETE RESTRICT,FOREIGN KEY(manifest_id,project_id) REFERENCES render_manifests(id,project_id) ON DELETE RESTRICT,FOREIGN KEY(output_asset_id,project_id) REFERENCES assets(id,project_id) ON DELETE RESTRICT);
